// Direct touch control of the original key-driven UI. Taps and drags on the game screen
// become cursor moves, camera pans and key presses, depending on which screen is showing.
// The game code under src/game is regenerated by the transpiler, so everything here reaches
// its (TypeScript-private) state through the typed views below instead of editing it.

import { App } from "../game/App";
import { Engine } from "../game/Engine";
import { GameData } from "../game/GameData";
import { GameUi } from "../game/GameUi";
import { Device } from "../runtime/midp";
import { KEY, buzz, capture, press, release, tapKey } from "./input";
import { buttonFocusRect, carouselZone, cornerKey, confirmAgrees, rowFocusRect, softZoneGame, type Rect } from "./zones";

interface AppView {
  state: number;
}

interface UiView {
  state: number;
  cameraX: number;
  cameraY: number;
  cursorX: number;
  cursorY: number;
  cursorVelocityX: number;
  cursorVelocityY: number;
  cursorDirX: number;
  cursorDirY: number;
  hoverInfoValid: boolean;
  hoveredObject: unknown;
  selectedBuilding: unknown;
  panelFocus: number;
  selectedButton: number;
  selectedRow: number;
  maxRow: number;
  panelScrollY: number;
  panelScrollMax: number;
  panelButtonIcons: { size: number };
  tradeResources: { size: number } | null;
  hoveredDepartment: number;
  selectedBonusResource: number;
  setState(s: number): void;
  setHint(text: string | null): void;
  getButtonHint(): string | null;
  getRowHint(): string | null;
}

interface MenuView {
  style: number;
  viewTop: number;
  viewBottom: number;
  viewLeft: number;
  viewRight: number;
  viewHeight: number;
  scrollPos: number;
  scrollTarget: number;
  contentHeight: number;
  items: Int32Array[];
  itemOffsets: Int32Array;
  itemCount: number;
  selectedIndex: number;
  fireCommand: number;
  selectItem(index: number, direction: number): void;
}

const app = App as unknown as AppView;
const ui = GameUi as unknown as UiView;

// App.state values
const APP_SCREEN = 0;
const APP_MENU = 1;
const APP_PAUSED = 2;
const APP_FADE = 3;
const APP_SPLASH = 8;
const APP_UPSELL = 10;

// App.getScreen() values
const SCREEN_LEVEL = 1;
const SCREEN_CAMPAIGN = 2;

// GameUi.state values
const UI_MESSAGE = -2;
const UI_ACTION_MENU = 2;
const UI_BUILD_MENU = 3;
const UI_PLACE = 4;
const UI_ATTACHMENT_MENU = 5;
const UI_PLACE_ATTACHMENT = 6;
const UI_STORAGE = 22;
const UI_TRADE = 25;
const PANELS_WITH_ROWS = new Set([10, 21, 26, 27]);
const CAMPAIGN_BONUS = 31;
const CAMPAIGN_TROOPS = 32;
const CAMPAIGN_ACTION_MENU = 35;
const CAMPAIGN_MESSAGE = 36;

const TRADE_ROW_HEIGHT = 18;
/** CSS px a finger may wander before a press counts as a drag. */
const DRAG_SLOP = 12;
/** CSS px around the cursor that count as tapping the cursor again. */
const NEAR_CURSOR = 30;

/** Building panels; GameUi.keyPressed treats states 11-20 like the plain map. */
function isPanel(state: number): boolean {
  return state === 10 || (state >= 21 && state <= 29);
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

function cell(image: number, horizontal: boolean): number {
  try {
    return horizontal ? Engine.getCellWidth(image) : Engine.getCellHeight(image);
  } catch {
    return 0;
  }
}

// ---------------------------------------------------------------- panel layout capture

interface PanelLayout {
  state: number;
  x: number;
  width: number;
  top: number;
  bottom: number;
  rows: { y: number; h: number }[];
  dividers: number[];
  buttonsY: number;
  buttonCount: number;
}

let panel: PanelLayout | null = null;

type DrawFn = (g: unknown, x: number, y: number, w: number) => number;

/** Wraps the panel draw helpers so each frame leaves behind where rows and buttons were drawn. */
function recordPanelLayout(): void {
  const G = GameUi as unknown as Record<string, DrawFn> & { drawPanelButtons(g: unknown, y: number): void };
  const wrap = (name: string, after: (x: number, y: number, w: number, h: number) => void) => {
    const original = G[name];
    G[name] = function (this: unknown, g, x, y, w) {
      const h = original.call(this, g, x, y, w);
      if (g !== null) after(x, y, w, h);
      return h;
    };
  };
  wrap("drawPanelTop", (x, y, w, h) => {
    panel = { state: ui.state, x, width: w, top: y, bottom: y + h, rows: [], dividers: [], buttonsY: -1, buttonCount: 0 };
  });
  const row = (_x: number, y: number, _w: number, h: number) => {
    if (!panel) return;
    panel.rows.push({ y, h });
    panel.bottom = y + h;
  };
  wrap("drawPanelRow", row);
  wrap("drawPanelDoubleRow", row);
  wrap("drawPanelDivider", (_x, y, _w, h) => {
    if (!panel) return;
    panel.dividers.push(y + h);
    panel.bottom = y + h;
  });
  wrap("drawPanelBottom", (_x, y, _w, h) => {
    if (panel) panel.bottom = y + h;
  });
  const drawButtons = G.drawPanelButtons;
  G.drawPanelButtons = function (this: unknown, g: unknown, y: number) {
    drawButtons.call(this, g, y);
    if (g !== null && panel) {
      panel.buttonsY = y;
      panel.buttonCount = ui.panelButtonIcons.size;
    }
  };
}

function currentPanel(): PanelLayout | null {
  return panel && panel.state === ui.state ? panel : null;
}

/** Mirrors the spacing in GameUi.drawPanelButtons. */
function buttonCenters(p: PanelLayout): number[] {
  const n = p.buttonCount;
  const first = n !== 1 ? p.x + 15 : p.x + p.width - 15;
  const step = Math.trunc((p.width - 30) / Math.max(n - 1, 1));
  return Array.from({ length: n }, (_, i) => first + step * i);
}

function finger(minGame: number, css: number): number {
  return Math.max(minGame, css / Math.max(cssPerPixel, 0.01));
}

function hitButton(p: PanelLayout, x: number, y: number): number {
  if (p.buttonsY < 0 || p.buttonCount === 0) return -1;
  const slop = finger(8, 18);
  const top = p.buttonsY - slop;
  const bottom = p.buttonsY + Math.max(22, cell(161, false)) + slop;
  if (y < top || y > bottom) return -1;
  const centers = buttonCenters(p);
  const reach = Math.max(12, (centers.length > 1 ? centers[1] - centers[0] : p.width) / 2);
  let best = -1;
  let bestDist = Infinity;
  centers.forEach((cx, i) => {
    const d = Math.abs(x - cx);
    if (d <= reach && d < bestDist) {
      best = i;
      bestDist = d;
    }
  });
  return best;
}

// ---------------------------------------------------------------- taps

let cssPerPixel = 1;

function nearCursor(x: number, y: number): boolean {
  const r = NEAR_CURSOR / cssPerPixel;
  return Math.abs(x - ui.cursorX) <= r && Math.abs(y - ui.cursorY) <= r;
}

function cursorIsStill(): boolean {
  return ui.cursorVelocityX === 0 && ui.cursorVelocityY === 0;
}

/** Forgets what was under the cursor, as GameUi.updateHoverInfo does while the cursor moves. */
function clearHover(): void {
  ui.hoveredObject = null;
  ui.selectedBuilding = null;
  ui.setHint(null);
  if (ui.state === 1) ui.setState(0);
}

/** First tap moves the cursor and lets the game show what is there; tapping it again is OK. */
function cursorTap(x: number, y: number, campaign: boolean): void {
  if (nearCursor(x, y) && cursorIsStill()) {
    tapKey(KEY.FIRE);
    return;
  }
  const w = Engine.screenWidth;
  const h = Engine.screenHeight;
  // The campaign map scrolls whenever the cursor leaves this inner band.
  const mx = campaign ? Math.trunc(w / 10) : 0;
  const my = campaign ? Math.trunc(h / 10) : 0;
  ui.cursorX = clamp(Math.round(x), mx, w - 2 - mx);
  ui.cursorY = clamp(Math.round(y), my, h - 3 - my);
  ui.cursorVelocityX = ui.cursorVelocityY = 0;
  ui.cursorDirX = ui.cursorDirY = 0;
  ui.hoverInfoValid = false;
  if (!campaign && (ui.state === 0 || ui.state === 1)) clearHover();
}

function directionKey(dx: number, dy: number): number {
  return Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? KEY.LEFT : KEY.RIGHT) : dy < 0 ? KEY.UP : KEY.DOWN;
}

/** Taps around a centre pick a direction; the centre and far outside have their own keys. */
function radialTap(x: number, y: number, cx: number, cy: number, inner: number, outer: number, center: number, outside: number): void {
  const dx = x - cx;
  const dy = y - cy;
  const d = Math.hypot(dx, dy);
  if (d <= inner) {
    if (center) tapKey(center);
  } else if (outer > 0 && d > outer) {
    if (outside) tapKey(outside);
  } else {
    tapKey(directionKey(dx, dy));
  }
}

function actionMenuTap(x: number, y: number, centerKey: number): void {
  const outer = Math.max(30, 1.3 * Math.max(cell(115, true), cell(115, false)));
  radialTap(x, y, ui.cursorX, ui.cursorY, 7, outer, centerKey, KEY.SOFT_RIGHT);
}

function carouselTap(x: number, y: number): void {
  const zone = carouselZone(x, y, Engine.screenWidth, Engine.screenHeight, cssPerPixel);
  tapKey(zone === "fire" ? KEY.FIRE : zone === "left" ? KEY.LEFT : zone === "right" ? KEY.RIGHT : zone === "up" ? KEY.UP : KEY.DOWN);
}

function zoneAt(width = Engine.screenWidth, height = Engine.screenHeight): { w: number; h: number } {
  return softZoneGame(width, height, cssPerPixel, cell(151, true), cell(151, false));
}

function softKeyRowTop(): number {
  return Engine.screenHeight - zoneAt().h;
}

function panelTap(x: number, y: number): void {
  const p = currentPanel();
  if (!p) return;
  const button = hitButton(p, x, y);
  if (button >= 0) {
    if (ui.panelFocus === 3 && ui.selectedButton === button) {
      tapKey(KEY.FIRE);
      return;
    }
    ui.panelFocus = 3;
    ui.selectedButton = button;
    if (ui.state === UI_TRADE) ui.selectedRow = -1;
    ui.setHint(ui.getButtonHint());
    Engine.playSound(30);
    return;
  }
  const inside = x >= p.x - 4 && x <= p.x + p.width + 4 && y >= p.top - 4 && y <= p.bottom + 4;
  if (!inside) {
    if (y < softKeyRowTop()) tapKey(KEY.SOFT_RIGHT);
    return;
  }
  const leftHalf = x < p.x + p.width / 2;
  if (ui.state === UI_TRADE && p.dividers.length > 0 && ui.tradeResources) {
    const listTop = p.dividers[0];
    const last = p.rows[p.rows.length - 1];
    const listBottom = last ? last.y + last.h : p.bottom;
    const slop = finger(4, 10);
    if (y < listTop - slop || y > listBottom + slop) return;
    const row = Math.floor((y - listTop + ui.panelScrollY) / TRADE_ROW_HEIGHT);
    if (row < 0 || row >= ui.tradeResources.size) return;
    if (ui.panelFocus !== 3 && ui.selectedRow === row) {
      tapKey(leftHalf ? KEY.LEFT : KEY.RIGHT);
    } else {
      ui.panelFocus = 1;
      ui.selectedRow = row;
      ui.setHint(null);
      Engine.playSound(30);
    }
    return;
  }
  if (PANELS_WITH_ROWS.has(ui.state)) {
    const rows = p.rows.slice(0, ui.maxRow + 1);
    const slop = finger(4, 10);
    let row = -1;
    let best = Infinity;
    rows.forEach((r, i) => {
      const dist = Math.abs(y - (r.y + r.h / 2));
      if (dist <= r.h / 2 + slop && dist < best) {
        row = i;
        best = dist;
      }
    });
    if (row < 0) return;
    if (ui.panelFocus === 1 && ui.selectedRow === row) {
      tapKey(leftHalf ? KEY.LEFT : KEY.RIGHT);
    } else {
      ui.panelFocus = 1;
      ui.selectedRow = row;
      ui.setHint(ui.getRowHint());
      Engine.playSound(30);
    }
  }
}

function levelTap(x: number, y: number): void {
  switch (ui.state) {
    case UI_MESSAGE:
      tapKey(KEY.FIRE);
      return;
    case -1:
      return;
    case 7:
    case 8:
    case 9:
      // The preview and the blank area agree; the bottom-right corner cancels.
      tapKey(confirmAgrees(x, y, Engine.screenWidth, Engine.screenHeight, cssPerPixel, cell(151, true), cell(151, false)) ? KEY.SOFT_LEFT : KEY.SOFT_RIGHT);
      return;
    case UI_ACTION_MENU:
      actionMenuTap(x, y, KEY.FIRE);
      return;
    case UI_BUILD_MENU:
    case UI_ATTACHMENT_MENU:
      carouselTap(x, y);
      return;
  }
  if (isPanel(ui.state)) panelTap(x, y);
  else cursorTap(x, y, false);
}

function bonusTap(x: number, y: number): void {
  const options = GameData.regionRewardOptions[ui.hoveredDepartment]?.length ?? 0;
  const size = cell(104, true) || 18;
  const width = size * options + 16;
  const left = (Engine.screenWidth >> 1) - (width >> 1);
  const cy = Engine.screenHeight >> 1;
  if (x < left - 4 || x > left + width + 4 || Math.abs(y - cy) > size) {
    if (y < softKeyRowTop()) tapKey(KEY.SOFT_RIGHT);
    return;
  }
  const i = clamp(Math.floor((x - left - 8) / size), 0, options - 1);
  if (i === ui.selectedBonusResource) tapKey(KEY.FIRE);
  else ui.selectedBonusResource = i;
}

function campaignTap(x: number, y: number): void {
  switch (ui.state) {
    case CAMPAIGN_BONUS:
      bonusTap(x, y);
      return;
    case CAMPAIGN_TROOPS:
      carouselTap(x, y);
      return;
    case 33:
    case 34:
    case CAMPAIGN_MESSAGE:
      tapKey(KEY.FIRE);
      return;
    case CAMPAIGN_ACTION_MENU:
      actionMenuTap(x, y, 0);
      return;
  }
  cursorTap(x, y, true);
}

function menuItemAt(m: MenuView, y: number): number {
  const top = m.viewTop + (m.viewHeight >> 1) - m.scrollPos;
  for (let i = 0; i < m.itemCount; i++) {
    if (y >= top + m.itemOffsets[i] && y < top + m.itemOffsets[i + 1]) return i;
  }
  return -1;
}

function menuTap(x: number, y: number): void {
  const m = App.getTopMenu() as unknown as MenuView | null;
  if (!m) return;
  if (y < m.viewTop || y > m.viewBottom || x < m.viewLeft - 8 || x > m.viewRight + 8) return;
  const i = menuItemAt(m, y);
  if (i < 0) return;
  const type = m.items[i][0];
  if (type <= 200) {
    if (m.fireCommand !== -1) tapKey(KEY.FIRE);
    return;
  }
  const adjustable = type === 206 || type === 207;
  if (i !== m.selectedIndex) {
    m.selectItem(i, -1);
    if (adjustable) return;
  } else if (adjustable) {
    tapKey(x < (m.viewLeft + m.viewRight) / 2 ? KEY.LEFT : KEY.RIGHT);
    return;
  }
  tapKey(KEY.FIRE);
}

function onTap(x: number, y: number): void {
  switch (app.state) {
    case APP_MENU:
      menuTap(x, y);
      return;
    case APP_PAUSED:
      tapKey(KEY.SOFT_RIGHT);
      return;
    case APP_FADE:
    case APP_SPLASH:
    case APP_UPSELL:
      tapKey(KEY.FIRE);
      return;
    case APP_SCREEN:
      if (App.getScreen() === SCREEN_LEVEL) levelTap(x, y);
      else if (App.getScreen() === SCREEN_CAMPAIGN) campaignTap(x, y);
  }
}

// ---------------------------------------------------------------- drags

interface Drag {
  move(dx: number, dy: number): void;
  end(vx: number, vy: number, dx: number, dy: number): void;
}

let inertia: { vx: number; vy: number; context: string } | null = null;

function panContext(): string | null {
  if (app.state !== APP_SCREEN) return null;
  if (App.getScreen() === SCREEN_LEVEL) {
    const s = ui.state;
    if (s === 0 || s === 1 || s === UI_PLACE || s === UI_PLACE_ATTACHMENT || (s >= 11 && s <= 20)) return "level";
  } else if (App.getScreen() === SCREEN_CAMPAIGN && ui.state === 30) {
    return "campaign";
  }
  return null;
}

let panRemX = 0;
let panRemY = 0;

function panBy(dx: number, dy: number): void {
  panRemX -= dx;
  panRemY -= dy;
  const ix = Math.trunc(panRemX);
  const iy = Math.trunc(panRemY);
  panRemX -= ix;
  panRemY -= iy;
  ui.cameraX += ix;
  ui.cameraY += iy;
  if (ix || iy) ui.hoverInfoValid = false;
}

function cameraDrag(context: string): Drag {
  inertia = null;
  panRemX = panRemY = 0;
  let lastX = 0;
  let lastY = 0;
  return {
    move(dx, dy) {
      panBy(dx - lastX, dy - lastY);
      lastX = dx;
      lastY = dy;
    },
    end(vx, vy) {
      if (Math.hypot(vx, vy) > 0.05) inertia = { vx, vy, context };
    },
  };
}

function menuDrag(): Drag | null {
  const m = App.getTopMenu() as unknown as MenuView | null;
  if (!m || m.contentHeight <= m.viewHeight) return null;
  const start = m.scrollPos;
  return {
    move(_dx, dy) {
      const target = Math.round(clamp(start - dy, m.viewHeight >> 1, m.contentHeight - (m.viewHeight >> 1)));
      m.scrollTarget = m.scrollPos = target;
      // Text pages track their position through the item that holds the view centre.
      if (m.items[m.selectedIndex][0] <= 200) {
        for (let i = 0; i < m.itemCount; i++) {
          if (target >= m.itemOffsets[i] && target < m.itemOffsets[i + 1] && m.items[i][0] <= 200) m.selectedIndex = i;
        }
      }
    },
    end() {},
  };
}

function storageDrag(): Drag {
  const start = ui.panelScrollY;
  return {
    move(_dx, dy) {
      ui.panelScrollY = Math.round(clamp(start - dy, 0, ui.panelScrollMax));
    },
    end() {},
  };
}

function tradeDrag(): Drag | null {
  const rows = ui.tradeResources?.size ?? 0;
  if (ui.panelFocus === 3 || rows === 0) return null;
  const start = ui.selectedRow;
  return {
    move(_dx, dy) {
      ui.selectedRow = clamp(start - Math.round(dy / TRADE_ROW_HEIGHT), 0, rows - 1);
    },
    end() {},
  };
}

/** Text boxes scroll while an arrow key is held, so the drag holds one. */
function messageDrag(): Drag {
  let held = 0;
  const hold = (code: number) => {
    if (code === held) return;
    if (held) release(held);
    held = code;
    if (code) press(code);
  };
  return {
    move(_dx, dy) {
      hold(dy < -6 ? KEY.DOWN : dy > 6 ? KEY.UP : 0);
    },
    end() {
      hold(0);
    },
  };
}

/** A flick acts as one arrow key; `follow` makes the content move with the finger. */
function swipe(follow: boolean): Drag {
  return {
    move() {},
    end(_vx, _vy, dx, dy) {
      if (Math.hypot(dx, dy) < 16 / cssPerPixel) return;
      tapKey(directionKey(follow ? -dx : dx, follow ? -dy : dy));
    },
  };
}

function beginDrag(): Drag | null {
  if (app.state === APP_MENU) return menuDrag();
  if (app.state !== APP_SCREEN) return null;
  const pan = panContext();
  if (pan) return cameraDrag(pan);
  const screen = App.getScreen();
  const s = ui.state;
  if (screen === SCREEN_LEVEL) {
    if (s === UI_MESSAGE) return messageDrag();
    if (s === UI_STORAGE) return storageDrag();
    if (s === UI_TRADE) return tradeDrag();
    if (s === UI_ACTION_MENU) return swipe(false);
    if (s === UI_BUILD_MENU || s === UI_ATTACHMENT_MENU) return swipe(true);
  } else if (screen === SCREEN_CAMPAIGN) {
    if (s === CAMPAIGN_MESSAGE) return messageDrag();
    if (s === CAMPAIGN_ACTION_MENU) return swipe(false);
    if (s === CAMPAIGN_BONUS || s === CAMPAIGN_TROOPS) return swipe(true);
  }
  return null;
}

/** Called every animation frame; carries a flicked map on until it slows down. */
export function updateTouch(dtMs: number): void {
  if (!inertia) return;
  if (panContext() !== inertia.context) {
    inertia = null;
    return;
  }
  panBy(inertia.vx * dtMs, inertia.vy * dtMs);
  const decay = Math.exp(-dtMs / 220);
  inertia.vx *= decay;
  inertia.vy *= decay;
  if (Math.hypot(inertia.vx, inertia.vy) < 0.02) inertia = null;
}

// ---------------------------------------------------------------- pointer plumbing

interface Gesture {
  id: number;
  startX: number;
  startY: number;
  corner: number;
  dragging: boolean;
  drag: Drag | null;
  samples: { t: number; x: number; y: number }[];
}

export function installTouchScreen(canvas: HTMLCanvasElement, onAnyInput: () => void): void {
  recordPanelLayout();
  let g: Gesture | null = null;

  const toGame = (e: PointerEvent) => {
    const r = canvas.getBoundingClientRect();
    cssPerPixel = r.width / Math.max(1, Device.width);
    return { x: (e.clientX - r.left) / cssPerPixel, y: (e.clientY - r.top) / cssPerPixel };
  };

  const cornerAt = (x: number, y: number) => {
    const which = cornerKey(x, y, Device.width, Device.height, cssPerPixel, cell(151, true), cell(151, false));
    return which === "left" ? KEY.SOFT_LEFT : which === "right" ? KEY.SOFT_RIGHT : 0;
  };

  canvas.addEventListener("pointerdown", (e) => {
    if (g || (e.pointerType === "mouse" && e.button !== 0)) return;
    e.preventDefault();
    capture(canvas, e.pointerId);
    onAnyInput();
    buzz();
    inertia = null;
    const p = toGame(e);
    const corner = cornerAt(p.x, p.y);
    if (corner) press(corner);
    g = { id: e.pointerId, startX: e.clientX, startY: e.clientY, corner, dragging: false, drag: null, samples: [{ t: e.timeStamp, ...p }] };
  });

  canvas.addEventListener("pointermove", (e) => {
    if (!g || e.pointerId !== g.id || g.corner) return;
    const p = toGame(e);
    g.samples.push({ t: e.timeStamp, ...p });
    while (g.samples.length > 2 && e.timeStamp - g.samples[0].t > 80) g.samples.shift();
    if (!g.dragging) {
      if (Math.hypot(e.clientX - g.startX, e.clientY - g.startY) < DRAG_SLOP) return;
      g.dragging = true;
      g.drag = beginDrag();
    }
    g.drag?.move((e.clientX - g.startX) / cssPerPixel, (e.clientY - g.startY) / cssPerPixel);
  });

  const finish = (e: PointerEvent, cancelled: boolean) => {
    if (!g || e.pointerId !== g.id) return;
    const gesture = g;
    g = null;
    if (gesture.corner) {
      release(gesture.corner);
      return;
    }
    // A short slide on a screen that does not scroll is still a tap.
    if (!gesture.dragging || !gesture.drag) {
      const moved = Math.hypot(e.clientX - gesture.startX, e.clientY - gesture.startY);
      if (!cancelled && moved < 48) {
        const p = toGame(e);
        onTap(p.x, p.y);
      }
      return;
    }
    const first = gesture.samples[0];
    const last = gesture.samples[gesture.samples.length - 1];
    const dt = Math.max(1, last.t - first.t);
    const recent = e.timeStamp - last.t < 60;
    const vx = recent && !cancelled ? (last.x - first.x) / dt : 0;
    const vy = recent && !cancelled ? (last.y - first.y) / dt : 0;
    gesture.drag?.end(vx, vy, (e.clientX - gesture.startX) / cssPerPixel, (e.clientY - gesture.startY) / cssPerPixel);
  };
  canvas.addEventListener("pointerup", (e) => finish(e, false));
  canvas.addEventListener("pointercancel", (e) => finish(e, true));
  canvas.addEventListener("contextmenu", (e) => e.preventDefault());
}

/** Game-pixel box around the selected panel row or button, for the touch highlight. */
export function selectionRect(): Rect | null {
  if (app.state !== APP_SCREEN || App.getScreen() !== SCREEN_LEVEL) return null;
  const p = currentPanel();
  if (!p) return null;
  if (ui.panelFocus === 3 && p.buttonsY >= 0 && p.buttonCount > 0 && ui.selectedButton >= 0 && ui.selectedButton < p.buttonCount) {
    return buttonFocusRect(buttonCenters(p)[ui.selectedButton], p.buttonsY);
  }
  if (ui.panelFocus === 1 && PANELS_WITH_ROWS.has(ui.state)) {
    const row = p.rows[ui.selectedRow];
    if (!row) return null;
    return rowFocusRect(p.x, row.y, p.width, row.h);
  }
  return null;
}

/** CSS size of the soft-key corners for the current canvas. */
export function softZoneCss(cssPerPixel: number, gameW: number, gameH: number): { w: number; h: number } {
  const zone = softZoneGame(gameW, gameH, cssPerPixel, cell(151, true), cell(151, false));
  return { w: zone.w * cssPerPixel, h: zone.h * cssPerPixel };
}

/** Debug hooks for driving taps from the console or tests. */
export const touchDebug = {
  tap: onTap,
  panel: () => currentPanel(),
  buttons: () => {
    const p = currentPanel();
    return p ? buttonCenters(p).map((x) => ({ x, y: p.buttonsY })) : [];
  },
};
